// src/app/index.tsx: the first route of a new app. Route files stay thin: they render a screen from
// src/features/. The first real feature (scaffold-feature-screen) replaces this route and its screen.
import { HomeScreen } from '@/features/home/home-screen';

export default function HomeRoute(): React.JSX.Element {
  return <HomeScreen />;
}

// src/features/home/home-screen.tsx: the starter screen of a new app, a pure view. It shows no text
// yet: words reach the screen through the message catalogs (i18n-strings-and-catalogs), never as
// literal strings, and colours through the theme (design-system-structure). The first real feature
// (scaffold-feature-screen) replaces it.
import { StyleSheet, View } from 'react-native';

export function HomeScreen(): React.JSX.Element {
  return <View style={styles.screen} testID="home.screen" />;
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
});

// src/features/home/home-screen.test.tsx
// no-providers: the starter screen reads nothing from context (no copy, theme or store yet)
import { render, screen } from '@testing-library/react-native';

import { HomeScreen } from './home-screen';

describe('HomeScreen', () => {
  it('renders the starter screen under its testID', async () => {
    await render(<HomeScreen />);

    expect(screen.getByTestId('home.screen')).toBeOnTheScreen();
  });
});

